CREATE TABLE IF NOT EXISTS records(kind TEXT NOT NULL,tenant TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(kind,tenant,id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,campaign TEXT NOT NULL,kind TEXT NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'queued',tries INTEGER NOT NULL DEFAULT 0,available INTEGER NOT NULL DEFAULT 0,lease INTEGER NOT NULL DEFAULT 0,error TEXT,UNIQUE(tenant,campaign,kind,revision));
CREATE TABLE IF NOT EXISTS spend(id TEXT PRIMARY KEY,tenant TEXT NOT NULL,campaign TEXT NOT NULL,reserved REAL NOT NULL,actual REAL,trace TEXT);
CREATE TABLE IF NOT EXISTS publications(tenant TEXT NOT NULL,campaign TEXT NOT NULL,revision INTEGER NOT NULL,data TEXT NOT NULL,PRIMARY KEY(tenant,campaign,revision));
CREATE TABLE IF NOT EXISTS events(site TEXT NOT NULL,kind TEXT NOT NULL,time TEXT NOT NULL);
